//! Offline declaration evidence and complete cleaned-table publication.

use super::entity_ingestion::EntitySearchPipelineError;
use crate::domain::models::declaration_cleaning::{
    CapturedMemberDeclarations, CleanedDeclarations,
};

/// Storage boundary for offline declaration cleaning.
pub trait DeclarationCleaningStorage: Clone + Send + Sync + 'static {
    /// Replays raw source evidence and checks it against the saved projections.
    fn read_captured_declarations(
        &self,
    ) -> impl Future<Output = Result<Vec<CapturedMemberDeclarations>, EntitySearchPipelineError>> + Send;

    /// Publishes both completed tables together, refusing to overwrite an existing result.
    fn publish_cleaned_declarations(
        &self,
        cleaned: &CleanedDeclarations,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
}
//! Boundaries for checked cleaned evidence, statistical scores, and complete output.
use super::entity_ingestion::EntitySearchPipelineError;
use crate::domain::models::{
    declaration_resolution::{ResolutionInput, ResolvedDeclarations, ScoredPairs, ScoringInput},
    entity_ingestion::EntityIngestionError,
};

/// Storage for one immutable declaration resolution run.
pub trait DeclarationResolutionStorage: Clone + Send + Sync + 'static {
    /// Reads and checks the cleaned observation and funding tables together.
    fn read_resolution_input(
        &self,
    ) -> impl Future<Output = Result<ResolutionInput, EntityIngestionError>> + Send;
    /// Publishes every completed output together without replacement.
    fn publish_resolution(
        &self,
        result: &ResolvedDeclarations,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Namespace for local provisional identities.
    fn resolution_run_key(&self) -> String;
}
/// Statistical scoring port. The implementation must report its actual model/runtime.
pub trait FunderScorer: Send + Sync {
    /// Scores bounded candidate profile pairs without assigning identities.
    fn score(
        &self,
        input: &ScoringInput,
    ) -> impl Future<Output = Result<ScoredPairs, EntityIngestionError>> + Send;
}
//! Parquet replay and publication for offline declaration cleaning.

use std::{
    collections::{BTreeMap, HashMap},
    fs::File,
    path::Path,
    sync::Arc,
};

use arrow::{
    datatypes::{DataType, Field, Schema},
    json::{ArrayWriter, ReaderBuilder},
};
use chrono::{DateTime, NaiveDate, Utc};
use parquet::arrow::{
    arrow_reader::ParquetRecordBatchReaderBuilder, async_writer::AsyncArrowWriter,
};
use serde::{Deserialize, Serialize};
use tokio::fs;
use uuid::Uuid;

use super::{
    ExposedDataPipeline, declaration_ingestion::declarations_schema,
    declaration_source::replay_declaration,
};
use crate::domain::{
    models::{
        declaration_cleaning::{CapturedMemberDeclarations, CleanedDeclarations},
        declaration_ingestion::{
            CapturedDeclaration, CapturedFundingEntry, DeclarationId, MemberAsId,
        },
    },
    repositories::{
        declaration_cleaning::DeclarationCleaningStorage,
        entity_ingestion::EntitySearchPipelineError,
    },
};

impl DeclarationCleaningStorage for ExposedDataPipeline {
    async fn read_captured_declarations(
        &self,
    ) -> Result<Vec<CapturedMemberDeclarations>, EntitySearchPipelineError> {
        if fs::try_exists(self.cleaned_declarations_path())
            .await
            .map_err(read_error)?
        {
            return Err(write_error("cleaned declarations already exist"));
        }
        let directory = self.raw_path().join("declarations");
        let mut files = fs::read_dir(&directory).await.map_err(read_error)?;
        let mut paths = Vec::new();
        while let Some(file) = files.next_entry().await.map_err(read_error)? {
            let path = file.path();
            if path
                .extension()
                .is_some_and(|extension| extension == "parquet")
            {
                paths.push(path);
            }
        }
        paths.sort();
        if paths.is_empty() {
            return Err(read_error("no raw declaration partitions found"));
        }
        paths
            .into_iter()
            .map(|path| {
                read_partition(&path)
                    .map_err(|error| read_error(format!("{}: {error}", path.display())))
            })
            .collect()
    }

    async fn publish_cleaned_declarations(
        &self,
        cleaned: &CleanedDeclarations,
    ) -> Result<(), EntitySearchPipelineError> {
        let destination = self.cleaned_declarations_path();
        if fs::try_exists(&destination).await.map_err(write_error)? {
            return Err(write_error("cleaned declarations already exist"));
        }
        let parent = destination
            .parent()
            .expect("cleaned declarations have a parent");
        fs::create_dir_all(parent).await.map_err(write_error)?;
        let staging = parent.join(format!(".declarations-{}", Uuid::now_v7()));
        fs::create_dir(&staging).await.map_err(write_error)?;
        let result = async {
            write_table(
                &staging.join("funding_entries.parquet"),
                funding_schema(),
                &cleaned.funding_entries,
            )
            .await?;
            write_table(
                &staging.join("funders.parquet"),
                funders_schema(),
                &cleaned.funders,
            )
            .await?;
            fs::rename(&staging, &destination)
                .await
                .map_err(write_error)
        }
        .await;
        if result.is_err() {
            let _ = fs::remove_dir_all(&staging).await;
        }
        result
    }
}

